    if not cart:
        raise ConflictError('The cart is empty', code='CART_EMPTY')
    lines = []
    total = Decimal("0")
    for item in cart:
        product = conn.execute('SELECT id, price, stock FROM "products" WHERE id = %s FOR UPDATE', (item["product_id"],)).fetchone()
        if product is None or item["quantity"] > product["stock"]:
            raise ConflictError('One or more products are out of stock', code='OUT_OF_STOCK', details={"product_id": str(item["product_id"])})
        lines.append((product["id"], item["quantity"], product["price"]))
        total += product["price"] * item["quantity"]
    order = conn.execute('INSERT INTO "orders" ("user_id", "status", "total", "shipping_address") VALUES (%s, %s, %s, %s) RETURNING *', (principal.user_id, 'pending', total, body.get("shipping_address"))).fetchone()
    for product_id, quantity, price in lines:
        conn.execute('INSERT INTO "order_items" ("order_id", "product_id", quantity, unit_price) VALUES (%s, %s, %s, %s)', (order["id"], product_id, quantity, price))
        conn.execute('UPDATE "products" SET stock = stock - %s WHERE id = %s', (quantity, product_id))
    conn.execute('DELETE FROM "cart_items" WHERE "user_id" = %s', (principal.user_id,))
